/// The colors for a mode.
pub const fn colors(mode: Mode) -> &'static Colors {
    match mode {
        Mode::Light => &LIGHT,
        Mode::Dark => &DARK,
    }
}

/// Corner radii. `FULL` means a pill: clamp it to half the height.
pub mod radius {
    pub const NONE: f32 = 0.0;
    pub const INNER: f32 = 10.0;
    pub const ELEMENT: f32 = 16.0;
    pub const CONTAINER: f32 = 19.0;
    pub const CHAT: f32 = 28.0;
    pub const PAGE: f32 = 45.0;
    pub const FULL: f32 = 9999.0;
}

