#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn modes_invert() {
        assert_eq!(LIGHT.background_body, palette::WHITE);
        assert_eq!(DARK.background_body, palette::BLACK);
        assert_eq!(LIGHT.text_primary, DARK.background_body);
        assert_eq!(DARK.text_primary, LIGHT.background_body);
        assert_eq!(LIGHT.accent, DARK.on_accent);
        assert_eq!(colors(Mode::Dark).accent, palette::WHITE);
    }
}
